const today = new Date();
const folderName = `${today.getFullYear()}-${today.getMonth()+1}-${today.getDate()}`;
const basePath = '/files';

const newItems = [];

items.forEach((item, index) => {
  for (const key of Object.keys(item.binary)) {
    const originalName = item.binary[key].fileName || key;

    // Añadimos un índice único para evitar sobrescribir
    const uniqueName = `${index}_${originalName}`;

    newItems.push({
      json: {
        folderName,
        fileName: uniqueName,
        path: `${basePath}/${folderName}/${uniqueName}`
      },
      binary: {
        data: item.binary[key] // siempre llamado "data"
      }
    });
  }
});

return newItems;

// items contiene cada archivo XML parseado a JSON
const newItems = [];

items.forEach(item => {
    const cfdis = item.json['cfdi:Comprobante'];

    // Si hay varias facturas juntas, cfdis puede ser un array
    const facturas = Array.isArray(cfdis) ? cfdis : [cfdis];

    facturas.forEach(factura => {
        const folio = factura.Folio;
        const subtotal = factura.SubTotal;
        const total = factura.Total;

        // IVA trasladado
        let iva = 0;
        if (factura['cfdi:Impuestos'] && factura['cfdi:Impuestos'].TotalImpuestosTrasladados) {
            iva = factura['cfdi:Impuestos'].TotalImpuestosTrasladados;
        }

        newItems.push({
            json: {
                Folio: folio,
                SubTotal: subtotal,
                IVA: iva,
                Total: total
            }
        });
    });
});

return newItems;

const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');

return [
