const result = [];

for (const item of items) {
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const file = item.binary[key];
      if (file.fileName.toLowerCase().endsWith('.xlsx') || file.fileName.toLowerCase().endsWith('.xls')) {
