return result;

for (const item of items) {
  // Accede a la columna de referencia de SQL
  let reference = item.json.Referencia;

  if (reference && typeof reference === 'string') {
    // 1. Elimina el prefijo 'F-LMM' (se usa /i para que no distinga mayúsculas/minúsculas)
    //    y usa .trim() para quitar cualquier espacio extra.
    let cleanedReference = reference.trim().replace(/^F-LMM/i, '');

    // 2. Crea una nueva columna con el valor limpio
    item.json.Cleaned_Factura = cleanedReference;
  }
}

return items;

// Obtiene todos los ítems de entrada
const items = $input.all();
const dateField = 'FECHA_FACTURA';

/**
 * Procesa strings en formato DD/MM/YYYY
 */
const parseDateString = (dateString) => {
    const datePart = String(dateString).split(' ')[0]; 
    const parts = datePart.split('/');

    if (parts.length === 3) {
        const day = parseInt(parts[0], 10);
        const month = parseInt(parts[1], 10) - 1; 
        const year = parseInt(parts[2], 10);
        return new Date(year, month, day);
    }
    return new Date('Invalid Date');
};

/**
 * Formatea fecha a 'YYYY-MM-DD'
 */
const formatDate = (date) => {
    if (!date || isNaN(date.getTime())) return null; 
    const yyyy = date.getFullYear();
    const mm = String(date.getMonth() + 1).padStart(2, '0');
    const dd = String(date.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
};

let minDate = null;
let maxDate = null;

for (const item of items) {
    const dateValue = item.json[dateField];
    if (dateValue) {
        let currentDate = new Date(dateValue);

        // Fallback si el constructor de Date falla
        if (isNaN(currentDate.getTime())) {
            currentDate = parseDateString(dateValue);
        }

        if (!isNaN(currentDate.getTime())) { 
            if (minDate === null || currentDate < minDate) {
                minDate = new Date(currentDate.getTime());
            }
            if (maxDate === null || currentDate > maxDate) {
                maxDate = new Date(currentDate.getTime());
            }
        }
    }
}

if (minDate && maxDate) {
    // Incremento forzado de 1 día a la fecha máxima
    const nextDay = new Date(maxDate.getTime());
    nextDay.setDate(nextDay.getDate() + 1);

    return [
        {
            json: {
                fechaInicio: formatDate(minDate),
                fechaFin: formatDate(nextDay), 
            }
        }
    ];
}

return [];

const columnsToKeep = [
    // CLAVE DE AGRUPACIÓN
    'FACTURA',
    // COLUMNAS DE LA IMAGEN
    'FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS', 
    'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL'
];

// Revisa si el primer ítem es una fila de encabezados
const isHeaderRow = items[0] && items[0].json.FACTURA === 'FACTURA';
const startIndex = isHeaderRow ? 1 : 0;

const result = [];

for (let i = startIndex; i < items.length; i++) {
    const item = items[i];

    // Combina datos de la raíz y de 'properties' en un solo objeto
    const allData = { ...item.json, ...(item.json.properties || {}) };

    const filteredItem = {};

    for (const column of columnsToKeep) {
        // Busca la clave original en el dato, ignorando espacios y mayúsculas/minúsculas
        const originalKey = Object.keys(allData).find(k => k.trim().toLowerCase().replace(/\s+/g, '_') === column.trim().toLowerCase().replace(/\s+/g, '_'));

        if (originalKey !== undefined) {
            filteredItem[column] = allData[originalKey];
        }
    }

    // Si la fila tiene valores, la agrega al resultado
    if (Object.keys(filteredItem).length > 0) {
        result.push({ json: filteredItem });
    }
}

return result;

const groups = {};

// Definimos SOLAMENTE las columnas numéricas para sumar (basado en la imagen)
const sumFields = [
    'TOTAL', 'SUBTOTAL', 'FLETE', 'RAD', 'EAD', 'SEGURO', 
    'ACUSE', 'COD', 'OTROS', 'DESCUENTO', 'IVA', 'IVA_RET'
];

// Definimos el orden FINAL y estricto de las columnas en el output
const outputOrder = [
    'FACTURA', 
    'FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS', 
    'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL'
];

// 1. Agrupar y Sumar los Datos
for (const item of items) {
    const data = item.json;
    // Normalizar la FACTURA (clave de agrupación)
    const facturaKey = String(data.FACTURA).trim().toUpperCase();

    if (!facturaKey) continue; 

    if (!groups[facturaKey]) {
        // Inicializar el grupo con clave y valores de referencia
        groups[facturaKey] = {
            FACTURA: facturaKey,
        };
        // Inicializar las sumas a 0
        sumFields.forEach(field => {
            groups[facturaKey][field] = 0;
        });
    }

    // Sumar todos los campos numéricos
    sumFields.forEach(field => {
        const value = parseFloat(data[field]) || 0;
        groups[facturaKey][field] += value;
    });
}

// 2. Formatear y Devolver el Resultado FORZANDO EL ORDEN
const result = [];
const numericFields = sumFields.concat(['TOTAL']); // Todos son numéricos para formatear

for (const key in groups) {
    if (groups.hasOwnProperty(key)) {
        const groupData = groups[key];
        const orderedItem = {};

        // Construir el objeto en el orden exacto de outputOrder
        for (const column of outputOrder) {
            let value = groupData[column];

            // Formatear valores numéricos a dos decimales
            if (numericFields.includes(column)) {
                 if (typeof value === 'number') {
                     value = value.toFixed(2);
                 }
            }

            orderedItem[column] = value;
        }

        result.push({
            json: orderedItem
        });
    }
}

// *** CÓDIGO AÑADIDO: ELIMINAR LA ÚLTIMA FILA DE TOTALES ***
if (result.length > 0) {
    result.pop(); 
}
// ********************************************************

return result;

const outputOrder = [
    'FACTURA',
    'FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS',
    'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL',
    'abono', 
    'RESULTADO'
];

const numericFields = [
    'TOTAL', 'SUBTOTAL', 'FLETE', 'RAD', 'EAD', 'SEGURO',
    'ACUSE', 'COD', 'OTROS', 'DESCUENTO', 'IVA', 'IVA_RET', 'abono'
];

// Función de parseo robusto para asegurar cálculos correctos
const parseValue = (value) => {
    if (value === null || value === undefined) return 0;
    // Convierte comas a puntos y elimina símbolos de moneda
    const cleanedString = String(value).replace(/[$,€]/g, '').replace(/,/g, '.').trim();
    return parseFloat(cleanedString) || 0; 
};

// Usaremos un Map para almacenar solo la fila final por FACTURA
const consolidatedData = new Map();

// =================================================================
// FASE 1: AGRUPACIÓN Y SELECCIÓN DEL REGISTRO FINAL
// =================================================================
for (const item of items) {
    const data = item.json;
    // La llave de agrupación es la factura limpia
    const facturaKey = data.Cleaned_Factura || data.FACTURA;

    // 1. Calcular el saldo pendiente (RESULTADO) de esta fila
    const totalValue = parseValue(data.TOTAL);
    const abonoValue = parseValue(data.abono); 
    const currentDifference = totalValue - abonoValue; 

    // 2. Determinar si esta es la fila a conservar
    if (!consolidatedData.has(facturaKey)) {
        // Es la primera vez que se ve la factura: la guardamos.
        consolidatedData.set(facturaKey, { 
            row: data, 
            difference: currentDifference // Guardamos el saldo para comparaciones futuras
        });
    } else {
        // Ya existe la factura: comparamos los saldos.
        const existingEntry = consolidatedData.get(facturaKey);

        // **Lógica clave:** Si el saldo actual es MENOR que el saldo guardado,
        // significa que hemos encontrado la línea con el abono aplicado.
        // Esto elimina la duplicidad y mantiene el registro correcto.
        if (currentDifference < existingEntry.difference) {
            consolidatedData.set(facturaKey, { 
                row: data, 
                difference: currentDifference 
            });
        }
    }
}

// =================================================================
// FASE 2: CÁLCULO Y FORMATO FINAL
// =================================================================
const result = [];

// Iteramos sobre las entradas seleccionadas (una sola fila por factura)
for (const entry of consolidatedData.values()) {
    const data = entry.row; // La fila con el saldo más bajo (abono aplicado)
    const finalRow = {};

    // Recalculamos el RESULTADO
    const totalValue = parseValue(data.TOTAL);
    const abonoValue = parseValue(data.abono);
    const difference = totalValue - abonoValue;

    // 1. Formatear la fila final según outputOrder
    for (const column of outputOrder) {
        let value = data[column];

        // Rellenar la columna FACTURA con el valor limpio
        if (column === 'FACTURA') {
            value = data.Cleaned_Factura || data.FACTURA;
        }

        // Asignar el RESULTADO calculado
        if (column === 'RESULTADO') {
            value = difference;
        }

        // Formatear valores numéricos a dos decimales
        if (numericFields.includes(column) || column === 'RESULTADO') {
            const numValue = parseValue(value);
            finalRow[column] = numValue.toFixed(2);
        } else {
            // Pasa la columna de texto como string
            finalRow[column] = String(value || '');
        }
    }

    // 2. Agregar la fila ÚNICA al resultado
    result.push({ json: finalRow });
}

return result;

const columnsToKeep = ['RASTREO', 'PESO', 'TOTAL', 'FACTURA', 'SUBTOTAL', 'FECHA_FACTURA', 'FLETE']; // 1. FLETE agregado al final

// Revisa si el primer ítem es una fila de encabezados
const isHeaderRow = items[0] && items[0].json.RASTREO === 'RASTREO';
const startIndex = isHeaderRow ? 1 : 0;

const result = [];

for (let i = startIndex; i < items.length; i++) {
	const item = items[i];

	// Combina datos de la raíz y de 'properties' en un solo objeto
	const allData = { ...item.json, ...(item.json.properties || {}) };

	const filteredItem = {};

	for (const column of columnsToKeep) {
		const originalKey = Object.keys(allData).find(k => k.trim().toLowerCase().replace(/\s+/g, '_') === column.trim().toLowerCase().replace(/\s+/g, '_'));

		if (originalKey !== undefined) {
			filteredItem[column] = allData[originalKey];
		}
	}

	// --- LÓGICA AGREGADA: 2. Formato de Fecha (DD/MM/YYYY -> YYYY-MM-DD sin hora) ---
    if (filteredItem.FECHA_FACTURA) {
        // Ejemplo: Toma "16/08/2025 12:00:00 a. m." y se queda con "16/08/2025"
        const datePart = String(filteredItem.FECHA_FACTURA).split(' ')[0]; 
        const parts = datePart.split('/'); // parts = ["16", "08", "2025"]

        if (parts.length === 3) {
            // Reordena a YYYY-MM-DD
            filteredItem.FECHA_FACTURA = `${parts[2]}-${parts[1]}-${parts[0]}`; 
        }
    }
	// --------------------------------------------------------------------------

	// Si la fila tiene valores, la agrega al resultado
	if (Object.keys(filteredItem).length > 0) {
		result.push({ json: filteredItem });
	}
}

return result;

for (const item of items) {
  // Accede a la columna de referencia de SQL
  let reference = item.json.FACTURA;

  if (reference && typeof reference === 'string') {
    // 1. Elimina el prefijo 'LMM' seguido de dos caracteres (por ejemplo, '01')
    //    y lo que esté antes, para dejar sólo lo que empieza con 'AD'.
    //    La expresión regular /^.*?(AD)/i busca desde el inicio (^)
    //    cualquier cosa (.*?) hasta el primer 'AD' y lo captura.
    //    La expresión regular a usar es: /^LMM\d{2}/i para los 5 caracteres
    //    o una más general si el patrón no es fijo.

    // **Modificación clave:** Elimina los primeros 5 caracteres: 'LMM' + '01'
    let cleanedReference = reference.trim().replace(/^LMM\d{2}/i, '');

    // 2. Crea una nueva columna con el valor limpio
    item.json.Cleaned_Factura = cleanedReference;
  }
}

return items;

let results = [];

// Procesa todos los ítems recibidos (sin limitarse al primero)
for (const item of $input.all()) {
  if (!item.binary) continue;

  // Recorre todas las llaves binarias del ítem actual
  for (const key of Object.keys(item.binary)) {
    const file = item.binary[key];
    const fileName = file.fileName;

    // Conversión a mayúsculas para comparación ciega
    const fileNameUpper = fileName.toUpperCase();
    const searchPattern = "MONTO MAYOR";

    // Filtro: extensión .zip Y presencia de la cadena (insensible a mayúsculas/minúsculas)
    if (fileName.toLowerCase().endsWith('.zip') && fileNameUpper.includes(searchPattern)) {
      results.push({
        json: {
          originalFileName: fileName,
          extractedFromKey: key
        },
        binary: {
          data: file // Mantiene el archivo original en la propiedad 'data'
        }
      });
    }
  }
}

return results;

let results = [];

// Procesa la totalidad de los ítems de entrada
for (const item of $input.all()) {
  if (!item.binary) continue;

  // Itera sobre cada archivo binario dentro del ítem
  for (const key of Object.keys(item.binary)) {
    const file = item.binary[key];
    const fileName = file.fileName;

    const fileNameUpper = fileName.toUpperCase();
    const searchPattern = "ECOMMERCE";
    const excludePattern = "MENOR";

    // Validación: debe ser .zip, contener "ECOMMERCE" y NO contener "MENOR"
    if (
      fileName.toLowerCase().endsWith('.zip') &&
      fileNameUpper.includes(searchPattern) &&
      !fileNameUpper.includes(excludePattern)
    ) {
      results.push({
        json: {
          originalFileName: fileName,
          extractedFromKey: key
        },
        binary: {
          data: file
        }
      });
    }
  }
}

return results;

let results = [];

// Procesa todos los ítems de entrada
for (const item of $input.all()) {
  if (!item.binary) continue;

  // Itera sobre todas las llaves binarias (file_0, file_1, etc.)
  for (const key of Object.keys(item.binary)) {
