return results;

const groups = {};
let globalTotals = {
    FLETE: 0, RAD: 0, EAD: 0, SEGURO: 0, ACUSE: 0, COD: 0, OTROS: 0,
    DESCUENTO: 0, SUBTOTAL: 0, IVA: 0, IVA_RET: 0, TOTAL: 0, "Flete_Alianza": 0
};

const sumFields = [
    'FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS', 
    'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL', 'Flete_Alianza'
];

$input.all().forEach(item => {
    const comprobante = item.json['cfdi:Comprobante'];
    if (!comprobante) return;

    const facturas = Array.isArray(comprobante) ? comprobante : [comprobante];

    facturas.forEach(factura => {
        let facturaKey = String(factura.Folio || "S/F").trim();

        if (!groups[facturaKey]) {
            groups[facturaKey] = {
                // 1-31
                GUIA: "", RASTREO: "", FACTURA: facturaKey, FECHA_FACTURA: factura.Fecha || "",
                ARGUMENTO: "", MANIFIESTO: "", DESTINO: "", FECHA_ENVIO: "", FECHA_ENTREGA: "",
                REFERENCIA: "", CTE_ORIGEN: "", NOM_ORIGEN: factura['cfdi:Emisor']?.Nombre || "",
                CTE_DESTINO: "", NOM_DESTINO: factura['cfdi:Receptor']?.Nombre || "",
                ESTADO: "", CODIGO_POSTAL: "", LOCALIDAD: "", COLONIA: "", CALLE: "", NUMERO: "",
                IMPORTE_GUIA: "", MODO_PAGO: factura.MetodoPago || "", TIPO_PAGO: factura.FormaPago || "",
                TIPO_ENTREGA: "", STATUS: "", CANTIDAD: "", PESO: "", VOLUMEN: "", TARIFA: "",
                CONTENIDO: "", DESCRIPCION: "",
                // 32-43 (Valores calculados)
                FLETE: 0, RAD: 0, EAD: 0, SEGURO: 0, ACUSE: 0, COD: 0, OTROS: 0,
                DESCUENTO: 0, SUBTOTAL: 0, IVA: 0, IVA_RET: 0, TOTAL: 0,
                // 44-45
                OBSERVACIONES: "", PERSONA_RECIBE: "",
                // 46-52 (Repetidos y específicos)
                IMPTE_ANTES_DE_DESCTO: 0, "FLETE ": 0, "RAD ": 0, "EAD ": 0, 
                OTROS_SERVICIOS: 0, "SEGURO ": 0, "TOTAL ": 0,
                // 53-54
                ES: "N",
                Flete_Alianza: 0
            };
        }

        let flete = 0, rad = 0, ead = 0, seguro = 0, acuse = 0, cod = 0, otros = 0;
        const conceptosRoot = factura['cfdi:Conceptos']?.['cfdi:Concepto'];
        const conceptos = Array.isArray(conceptosRoot) ? conceptosRoot : [conceptosRoot];

        conceptos.forEach(c => {
            if (!c) return;
            const desc = (c.Descripcion || "").toUpperCase();
            const imp = parseFloat(c.Importe || 0);

            if (desc.includes("FLETE")) flete += imp;
            else if (desc.includes("EAD") || desc.includes("ENTREGA A DOMICILIO")) ead += imp;
            else if (desc.includes("RAD") || desc.includes("RECOLECCION A DOMICILIO")) rad += imp;
            else if (desc.includes("SEGURO")) seguro += imp;
            else if (desc.includes("ACUSE")) acuse += imp;
            else if (desc.includes("COD")) cod += imp;
            else otros += imp;
        });

        const row = groups[facturaKey];
        const subtotal = parseFloat(factura.SubTotal || 0);
        const descuento = parseFloat(factura.Descuento || 0);
        const iva = parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosTrasladados || 0);
        const iva_ret = parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosRetenidos || 0);
        const total = parseFloat(factura.Total || 0);

        row.FLETE += flete;
        row.RAD += rad;
        row.EAD += ead;
        row.SEGURO += seguro;
        row.ACUSE += acuse;
        row.COD += cod;
        row.OTROS += otros;
        row.DESCUENTO += descuento;
        row.SUBTOTAL += subtotal;
        row.IVA += iva;
        row.IVA_RET += iva_ret;
        row.TOTAL += total;

        // Asignación de columnas repetidas (mismo valor)
        row.IMPTE_ANTES_DE_DESCTO = row.SUBTOTAL;
        row["FLETE "] = row.FLETE;
        row["RAD "] = row.RAD;
        row["EAD "] = row.EAD;
        row.OTROS_SERVICIOS = row.OTROS;
        row["SEGURO "] = row.SEGURO;
        row["TOTAL "] = row.TOTAL;

        row.Flete_Alianza += (flete * 0.39);

        // Globales
        globalTotals.FLETE += flete;
        globalTotals.RAD += rad;
        globalTotals.EAD += ead;
        globalTotals.SEGURO += seguro;
        globalTotals.ACUSE += acuse;
        globalTotals.COD += cod;
        globalTotals.OTROS += otros;
        globalTotals.DESCUENTO += descuento;
        globalTotals.SUBTOTAL += subtotal;
        globalTotals.IVA += iva;
        globalTotals.IVA_RET += iva_ret;
        globalTotals.TOTAL += total;
        globalTotals.Flete_Alianza += (flete * 0.39);
    });
});

const result = Object.values(groups).map(g => {
    const finalRow = {};
    Object.keys(g).forEach(key => {
        finalRow[key] = (typeof g[key] === 'number') ? g[key].toFixed(2) : g[key];
    });
    return { json: finalRow };
});

const finalTotalRow = {};
const firstRow = Object.values(groups)[0];
if (firstRow) {
    Object.keys(firstRow).forEach(key => {
        const cleanKey = key.trim();
        if (key === "FACTURA") finalTotalRow[key] = "TOTALES";
        else if (globalTotals.hasOwnProperty(cleanKey)) finalTotalRow[key] = globalTotals[cleanKey].toFixed(2);
        else if (key === "Flete_Alianza") finalTotalRow[key] = globalTotals.Flete_Alianza.toFixed(2);
        else if (key === "ES") finalTotalRow[key] = "N";
        else finalTotalRow[key] = "";
    });
    result.push({ json: finalTotalRow });
}

return result;

const items = $input.all();
if (items.length === 0) return [];

// 1. Extraer los nombres de las columnas (las llaves del JSON)
