let globalTotals = {
    FLETE: 0, RAD: 0, EAD: 0, SEGURO: 0, ACUSE: 0, COD: 0, OTROS: 0,
    DESCUENTO: 0, SUBTOTAL: 0, IVA: 0, IVA_RET: 0, TOTAL: 0, "FLETE ALIANZA": 0
