    facturas.forEach(factura => {
        // REGLA: Mantener prefijo original (sin limpieza de LMM)
        const facturaKey = String(factura.Folio || "S/F").trim();

        // Inicializar grupo si no existe para sumar facturas iguales
        if (!groups[facturaKey]) {
            groups[facturaKey] = { FACTURA: facturaKey };
            fields.forEach(f => groups[facturaKey][f] = 0);
            groups[facturaKey]['FLETE ALIANZA'] = 0;
        }

        // Extracción de datos
        const flete = parseFloat(factura.FLETE || 0);
        const ead = parseFloat(factura.EAD || 0);
        const descuento = parseFloat(factura.Descuento || factura.DESCUENTO || 0);

        const data = {
            FLETE: flete,
            RAD: parseFloat(factura.RAD || 0),
            EAD: ead,
            SEGURO: parseFloat(factura.SEGURO || 0),
            ACUSE: parseFloat(factura.ACUSE || 0),
            COD: parseFloat(factura.COD || 0),
