            IVA_RET: parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosRetenidos || 0)
        };

        // REGLA FLETE ALIANZA: FLETE + EAD - DESCUENTO
        const fAlianza = flete + ead - descuento;

        // Sumar al grupo (Agrupación)
        fields.forEach(f => groups[facturaKey][f] += data[f]);
        groups[facturaKey]['FLETE ALIANZA'] += fAlianza;

        // Sumar a totales globales
        fields.forEach(f => globalTotals[f] += data[f]);
        globalTotals['FLETE ALIANZA'] += fAlianza;
    });
});

